/*
 * prog30_escape_unescape.c
 *
 * Re‑implementation of the original program whose behaviour was
 * discovered by reverse‑engineering the obfuscated binary.
 *
 * The program expects three command line arguments:
 *
 *   prog30_escape_unescape <mode> <string>
 *
 * <mode> must be either "escape" or "unescape".
 *
 *   * escape   – converts the input string into a C‑style escaped
 *                representation.  The following characters are escaped:
 *
 *                  '\\'  ->  "\\\\"
 *                  '"'   ->  "\\\""
 *                  '\n'  ->  "\\n"
 *                  '\t'  ->  "\\t"
 *
 *                All other characters are copied unchanged.
 *
 *   * unescape – performs the inverse operation.  Recognised escape
 *                sequences are the same as above; any other sequence
 *                of the form "\\x" where x is not one of the above
 *                characters is treated as the literal character x.
 *
 * The implementation follows the limits observed in the original
 * binary:
 *
 *   • The input string must be at most 1023 characters long.
 *   • The output buffer is limited to 2047 characters (including the
 *     terminating NUL).  If the output would exceed this size the
 *     program prints "INVALID".
 *
 * Error handling mirrors the original binary:
 *
 *   • If argc < 3                → prints "USAGE"
 *   • If mode is not recognised → prints "INVALID_MODE"
 *   • If input length > 1023     → prints "INVALID"
 *   • If output length would exceed 2047 → prints "INVALID"
 *
 * The program writes the resulting string to stdout using puts().
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT   1023          /* observed limit in the original binary */
#define MAX_OUTPUT  2047          /* observed limit for the escaped string */

static void escape_string(const char *in, char *out, size_t out_sz)
{
    size_t out_len = 0;
    for (size_t i = 0; in[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)in[i];
        switch (c) {
            case '\\':
                if (out_len + 2 >= out_sz) { puts("INVALID"); exit(0); }
                out[out_len++] = '\\';
                out[out_len++] = '\\';
                break;
            case '"':
                if (out_len + 2 >= out_sz) { puts("INVALID"); exit(0); }
                out[out_len++] = '\\';
                out[out_len++] = '"';
                break;
            case '\n':
                if (out_len + 2 >= out_sz) { puts("INVALID"); exit(0); }
                out[out_len++] = '\\';
                out[out_len++] = 'n';
                break;
            case '\t':
                if (out_len + 2 >= out_sz) { puts("INVALID"); exit(0); }
                out[out_len++] = '\\';
                out[out_len++] = 't';
                break;
            default:
                if (out_len + 1 >= out_sz) { puts("INVALID"); exit(0); }
                out[out_len++] = c;
                break;
        }
    }
    out[out_len] = '\0';
    puts(out);
}

static void unescape_string(const char *in, char *out, size_t out_sz)
{
    size_t out_len = 0;
    for (size_t i = 0; in[i] != '\0'; ) {
        if (in[i] == '\\' && in[i+1] != '\0') {
            char esc = in[i+1];
            switch (esc) {
                case '\\':
                    if (out_len + 1 >= out_sz) { puts("INVALID"); exit(0); }
                    out[out_len++] = '\\';
                    i += 2;
                    break;
                case '"':
                    if (out_len + 1 >= out_sz) { puts("INVALID"); exit(0); }
                    out[out_len++] = '"';
                    i += 2;
                    break;
                case 'n':
                    if (out_len + 1 >= out_sz) { puts("INVALID"); exit(0); }
                    out[out_len++] = '\n';
                    i += 2;
                    break;
                case 't':
                    if (out_len + 1 >= out_sz) { puts("INVALID"); exit(0); }
                    out[out_len++] = '\t';
                    i += 2;
                    break;
                default:
                    /* Unknown escape – copy the character literally */
                    if (out_len + 1 >= out_sz) { puts("INVALID"); exit(0); }
                    out[out_len++] = esc;
                    i += 2;
                    break;
            }
        } else {
            if (out_len + 1 >= out_sz) { puts("INVALID"); exit(0); }
            out[out_len++] = in[i++];
        }
    }
    out[out_len] = '\0';
    puts(out);
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }

    char output[MAX_OUTPUT + 1];   /* +1 for the terminating NUL */

    if (strcmp(mode, "escape") == 0) {
        escape_string(input, output, sizeof(output));
    } else if (strcmp(mode, "unescape") == 0) {
        unescape_string(input, output, sizeof(output));
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
